<?php
abstract class CrudController extends Controller {protected string $table;protected string $pk;protected string $folder;protected string $label;protected array $fields=[];public function index():void{Auth::requireLogin();$this->view('shared/list',['title'=>$this->label,'rows'=>(new CrudModel())->all($this->table),'controller'=>$this->folder,'pk'=>$this->pk]);}public function form():void{Auth::requireRole(['administrador','recepcion']);$id=$this->id();$row=$id?(new CrudModel())->find($this->table,$this->pk,$id):[];$this->view('shared/form',['title'=>($id?'Editar ':'Nuevo ').$this->label,'row'=>$row,'fields'=>$this->fields,'controller'=>$this->folder,'id'=>$id]);}public function save():void{Auth::requireRole(['administrador','recepcion']);if($_SERVER['REQUEST_METHOD']!=='POST')$this->redirect($this->folder);(new CrudModel())->save($this->table,$this->pk,$_POST,(int)($_POST['id']??0));Session::flash('ok','Datos guardados correctamente.');$this->redirect($this->folder);}public function delete():void{Auth::requireRole(['administrador']);(new CrudModel())->deactivate($this->table,$this->pk,$this->id());Session::flash('ok','Registro desactivado.');$this->redirect($this->folder);}}

